def save(name,value): (root/name).write_text(json.dumps(value,ensure_ascii=False,indent=2),encoding='utf8',newline='\n')
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def model(name):
    p=root/name
    if not p.exists():
        source=root/'branding'/name
        if not source.exists():raise FileNotFoundError(name)
        # Move only this task's newly generated manifest to the repository root.
        if p.resolve().parent!=root.resolve() or source.resolve().parent!=(root/'branding').resolve():raise ValueError('unexpected path')
        source.rename(p)
    return json.loads(p.read_text(encoding='utf8'))
